let audioContext;function sound(kind){if(game.state.ui.mute||kind==='error'||kind==='ui')return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();const now=audioContext.currentTime;if(kind==='raidArrival'||kind==='petMilestone'){(kind==='petMilestone'?[523,659,784,1047]:[392,330,262]).forEach((frequency,index)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),at=now+index*.14;osc.type='square';osc.frequency.setValueAtTime(frequency,at);gain.gain.setValueAtTime(.028*(game.state.ui.volume??.5),at);gain.gain.exponentialRampToValueAtTime(.001,at+.12);osc.connect(gain).connect(audioContext.destination);osc.start(at);osc.stop(at+.13);});return;}const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type='square';osc.frequency.setValueAtTime(['deadline','raidWin','bossWin','ending','petMilestone'].includes(kind)?523:kind==='skill'?392:440,now);osc.frequency.exponentialRampToValueAtTime(['deadline','raidWin','bossWin','ending','petMilestone'].includes(kind)?784:523,now+.12);gain.gain.setValueAtTime(.025*(game.state.ui.volume??.5),now);gain.gain.exponentialRampToValueAtTime(.001,now+.18);osc.connect(gain).connect(audioContext.destination);osc.start(now);osc.stop(now+.2);}catch{}}
function playActionSound(fx){if(game.state.ui.mute)return;try{audioContext=audioContext||new (window.AudioContext||window.webkitAudioContext)();const notes=fx.notable?[523,659,784,1047]:fx.loot.length?[392,587]:fx.hits.some(hit=>hit.critical)?[330,494]:fx.hits.length?[220]:fx.empty?[165]:[];const now=audioContext.currentTime;notes.forEach((frequency,i)=>{const osc=audioContext.createOscillator(),gain=audioContext.createGain(),at=now+i*.075;osc.type='square';osc.frequency.setValueAtTime(frequency,at);gain.gain.setValueAtTime(.018*(game.state.ui.volume??.5),at);gain.gain.exponentialRampToValueAtTime(.001,at+.1);osc.connect(gain).connect(audioContext.destination);osc.start(at);osc.stop(at+.11);});}catch{}}
function cancelBattle(){if(cancelBattleAnimation)cancelBattleAnimation();cancelBattleAnimation=null;battleAnimating=false;battlePlayback=null;}
function battleSend(p={}){
  if(battleAnimating)return;
  const before=battleView.capture(game.state),feedbackBefore=actionEffects.capture(game.state);
  const result=game.dispatch('BATTLE',p);
  setActionFeedback(actionEffects.derive(feedbackBefore,game.state,result,'BATTLE',D));
  if(actionFeedback)playActionSound(actionFeedback);else sound(result.type);
  if(result.type==='error'){showToast(result.message);render();return;}
  if(before){
    battlePlayback=battleView.prepare(before,result);
    if(battlePlayback?.actions.length){
      battleAnimating=true;render();
      cancelBattleAnimation=battleView.play(app,battlePlayback,game.state.ui.battleSpeed,()=>{
        battleAnimating=false;battlePlayback=null;cancelBattleAnimation=null;if(result.type==='raidWin')tab='guild';lastAuto=Date.now()-(game.state.ui.battleSpeed===2?320:650);render();
      });
      return;
    }
  }
  battlePlayback=null;if(result.type==='raidWin')tab='guild';if(!game.state.expedition)showToast(result.message);render();
}
function send(type,p={}){if(type==='BATTLE'){battleSend(p);return;}if(battleAnimating&&type==='SET_AUTO'){game.dispatch(type,p);if('battle' in p){const control=app.querySelector('.combat-auto');if(control){control.textContent=`自動戦闘 ${game.state.expedition?.auto.battle?'ON':'OFF'}`;control.classList.toggle('is-on',!!game.state.expedition?.auto.battle);control.dataset.arg=JSON.stringify({battle:!game.state.expedition?.auto.battle});}}return;}if(battleAnimating&&type==='SET_UI'&&'battleSpeed' in p){game.dispatch(type,p);const control=app.querySelector('[data-act="speed"]');if(control)control.textContent=`速度 ${game.state.ui.battleSpeed}倍`;return;}const before=actionEffects.capture(game.state);motionActive=type==='STEP';const result=game.dispatch(type,p);if(result.type==='petLevel'){const effects=PG.basic(result.pet,result.toLevel,game.state.run.petSecond?.[result.pet]).milestones.filter(entry=>entry.level>result.fromLevel&&entry.level<=result.toLevel);petLevelAnimation={pet:result.pet,fromLevel:result.fromLevel,toLevel:result.toLevel,cost:result.cost,special:effects.length>0};clearTimeout(petLevelTimer);petLevelTimer=setTimeout(()=>{petLevelAnimation=null;document.querySelector('.pet-level-backdrop')?.remove();},effects.length?4400:2700);}setActionFeedback(actionEffects.derive(before,game.state,result,type,D));tutorialAdvance(type,result);if(type==='SELL_ITEM'||type==='SELL_STACK')selectedStackKey=null;const fresh=result.mapDiscoveries||[];if(fresh.length)mapReveal=[...new Set([...mapReveal,...fresh])];actionFeedback?playActionSound(actionFeedback):sound(result.type==='petLevel'&&petLevelAnimation?.special?'petMilestone':result.type);if(fresh.length)showToast(`地図を発見！ ${fresh.map(id=>mapAreaName(id)).join('・')}の霧が晴れた`);else if(result.type==='raidArrival'||result.type==='petLevel')document.querySelector('.toast')?.remove();else if(!actionFeedback||['trap','checkpoint'].includes(result.type)||type==='BATTLE'&&!game.state.expedition)showToast(result.message);else document.querySelector('.toast')?.remove();render();}
function showToast(msg){let el=document.querySelector('.toast');if(el)el.remove();el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3100);}
