function feedbackMarkup(){const fx=actionFeedback;if(!fx)return '';const loot=fx.loot.slice(0,3).map(item=>`<div class="reward-line rarity-${item.rarity}">${itemIcon(item.id,'reward-icon')}<span>${esc(D.items[item.id]?.name||item.id)}${item.count>1?` ×${item.count}`:''}</span><small>${esc(D.rarityLabels[item.rarity]||'')}</small></div>`).join('');const rest=fx.loot.length>3?`<small class="reward-rest">ほか${fx.loot.length-3}種類</small>`:'';const prize=fx.loot[0]?.rarity,lucky=prize==='legendary'?'伝説の発見！':prize==='epic'?'至宝を発見！':'レア獲得！';const heading=fx.notable?(fx.win?'勝利！ ':'')+lucky:fx.win?'勝利！':fx.kind==='gather'?(fx.empty?'今回は空振り':'採取成功！'):fx.loot.length?'戦利品を発見！':'';return `<div class="action-feedback ${fx.notable?'notable':''}" role="status" aria-live="polite">${fx.hits.slice(-6).map((hit,i)=>`<span class="damage-pop ${hit.side} ${hit.critical?'critical':''} ${hit.heal?'heal':''} ${hit.lightning?'lightning':''}" style="--i:${i}">${hit.heal?'+':'−'}${hit.amount}${hit.critical?' 会心！':hit.lightning?' ⚡':''}</span>`).join('')}${heading||loot||fx.gold?`<div class="reward-reveal ${fx.notable?'reward-rare':''}">${heading?`<b>${heading}</b>`:''}${loot}${rest}${fx.gold?`<small class="reward-gold">+${fx.gold}G</small>`:''}</div>`:''}</div>`;}
function dueText(r){if(r.due.type==='debt')return `返済${r.debtCount+1}/${D.C.totalDebts} ${r.due.amount}G`;if(r.due.type==='raid')return r.raidCount===D.C.totalRaids-1?`魔王襲来 ${D.C.totalRaids}/${D.C.totalRaids}`:`襲来${r.raidCount+1}/${D.C.totalRaids}`;if(r.due.type==='final')return '旧版の決戦';if(r.due.type==='ending')return '夜明け';return '天界';}
