function petBatchCost(id,count){let total=0;for(let level=game.petLevel(id);level<game.petLevel(id)+count;level++)total+=level<20?1:Math.ceil(level/20);return total;}
function petPanel(){const r=game.state.run,id=r.pet,pet=D.pets[id],level=game.petLevel(id),secondId=r.petSecond?.[id],basic=PG.basic(id,level,secondId),next=PG.basic(id,level+1,secondId),stats=PG.stats(id,level,E()),nextStats=PG.stats(id,level+1,E()),passive=PG.passive(id,level),nextPassive=PG.passive(id,level+1),options=D.catalog.pets.filter(option=>option.pet===pet.name),selected=secondId?PG.second(secondId,level):null,one=petBatchCost(id,1),five=petBatchCost(id,5);return `<section class="panel pet-panel"><div class="pet-workspace-top">${btn('← ギルドへ戻る','panel',{id:'reception'},'small')}</div>${title('仲間と相棒')}<div class="pet-hero-card">${portrait(sprites.pet(id),pet.name,'pet-large-art')}<div><span class="pet-kicker">PARTNER · ${esc(pet.role)}</span><h3>${esc(pet.nick)} <small>Lv.${level}</small></h3><p>育成点 ${r.petPoints} · 次のレベルまで ${one}点</p></div></div><div class="pet-stat-grid"><span>最大HP <b>${stats.hp}</b></span><span>攻撃力 <b>${stats.atk}</b></span><span>防御力 <b>${stats.def}</b></span><span>素早さ <b>${stats.speed}</b></span></div><div class="pet-skill-card"><span class="pet-kicker">基本スキル · 戦闘で自動発動</span><h3>${esc(basic.name)}</h3><p>敵単体に攻撃力の<strong>${basic.multiplier}%</strong>の物理ダメージ。</p>${basic.effects.length?`<ul>${basic.effects.map(effect=>`<li>${esc(effect)}</li>`).join('')}</ul>`:'<p class="note">追加効果はLv.10から解放。</p>'}<small>${esc(passive.text)}</small></div><div class="pet-growth-next"><b>次のレベル　Lv.${level+1}</b><span>攻撃倍率 ${basic.multiplier}% → <strong>${next.multiplier}%</strong></span>${stats.hp!==nextStats.hp?`<span>最大HP ${stats.hp} → ${nextStats.hp}</span>`:''}${stats.atk!==nextStats.atk?`<span>攻撃力 ${stats.atk} → ${nextStats.atk}</span>`:''}${passive.text!==nextPassive.text?`<span>${esc(nextPassive.text)}</span>`:''}${next.unlocked.map(effect=>`<em>NEW EFFECT! ${esc(effect.label)}</em>`).join('')}${basic.nextMilestone?`<small>次の節目 Lv.${basic.nextMilestone.level}：${esc(basic.nextMilestone.label)}</small>`:'<small>Lv.50以降も攻撃倍率が毎レベル伸びます。</small>'}</div><div class="pet-grow-actions">${btn(`育成点${one}で Lv.${level+1}へ`,'levelPet',{pet:id,count:1},'primary')}${r.petPoints>=five?btn(`5レベル育てる · ${five}点`,'levelPet',{pet:id,count:5},'small'):''}</div><div class="pet-skill-card"><span class="pet-kicker">第二スキル · Lv.20で選択</span>${level<20?`<p>Lv.20で候補から1つ選べます。あと${20-level}レベル。</p>`:`${selected?`<h3>${esc(selected.name)}</h3><p>${esc(selected.text)}</p>`:'<p>第二スキルを選べます。</p>'}<div class="pet-second-list">${options.map(option=>{const effect=PG.second(option.id,level);return `<div class="pet-second-option"><b>${esc(effect.name)}</b><small>${esc(effect.text)}</small>${btn(secondId===option.id?'選択中':'この技を選ぶ','petSkill',{id:option.id},`small ${secondId===option.id?'selected':''}`)}</div>`;}).join('')}</div>`}</div><h3>出会った相棒</h3><div class="pet-switch-list">${game.state.meta.discoveredPets.map(petId=>btn(`${portrait(sprites.pet(petId),D.pets[petId].name,'pet-inline-art')}${D.pets[petId].nick} Lv.${game.petLevel(petId)}`,'switchPet',{pet:petId},`small ${id===petId?'selected':''}`)).join('')}</div><div class="sep"></div><h3>仲間の編成</h3><div class="items">${Object.entries(D.allies).map(([allyId,ally])=>`<div class="item"><span class="name">${ally.name}<small>${ally.role} / ${ally.passive}</small></span>${r.alliesOwned.includes(allyId)?btn(r.activeAllies.includes(allyId)?'外す':'編成','allyToggle',{id:allyId,active:!r.activeAllies.includes(allyId)},'small'):r.raidCount?btn('雇う 150G','hireAlly',{id:allyId},'small'):''}</div>`).join('')}</div><p class="note">襲来を一度撃退すると仲間を雇えます。</p></section>`;}
function petLevelUI(){if(!petLevelAnimation)return '';const {pet,fromLevel,toLevel,cost}=petLevelAnimation,id=pet,nick=D.pets[id]?.nick||'相棒',old=PG.basic(id,fromLevel,game.state.run.petSecond?.[id]),now=PG.basic(id,toLevel,game.state.run.petSecond?.[id]),a=PG.stats(id,fromLevel,E()),b=PG.stats(id,toLevel,E()),newEffects=now.milestones.filter(entry=>entry.level>fromLevel&&entry.level<=toLevel),special=newEffects.length>0;return `<div class="pet-level-backdrop"><div class="pet-level-dialog ${special?'is-milestone':''}" role="dialog" aria-modal="true" aria-label="相棒のレベルアップ"><div class="pet-particles" aria-hidden="true"></div><span class="pet-kicker">${special?'SKILL POWER UP!':'LEVEL UP!'}</span>${portrait(sprites.pet(id),D.pets[id].name,'pet-level-art')}<h2>${esc(nick)} <small>Lv.${fromLevel} → Lv.${toLevel}</small></h2><div class="pet-level-gains"><span>最大HP <b>${a.hp} → ${b.hp}</b></span><span>攻撃力 <b>${a.atk} → ${b.atk}</b></span><span>${esc(now.name)} <b>${old.multiplier}% → ${now.multiplier}%</b></span></div>${newEffects.map(entry=>`<div class="pet-new-effect"><b>NEW EFFECT!</b> ${esc(entry.label)}</div>`).join('')}<small>育成点 −${cost}</small>${btn('成長を確認','petGrowthDismiss',{},'primary')}</div></div>`;}
function guildPanel(){const r=game.state.run;if(r.raidFirstChoice)return `<section class="panel">${title('新しい仲間を選ぶ')}<p>初めての襲来を一緒に切り抜けた仲間が、ギルドへの加入を申し出た。</p><div class="grid3">${['rio','nico','mina'].map(id=>btn(`${D.allies[id].name}<br><small>${D.allies[id].role}</small>`,'chooseAlly',{id},'small')).join('')}</div></section>`;if(panel==='reception')return `<section class="panel">${title('受付')}<div class="statusline">${dueText(r)}　${r.due.dueDay?`${r.due.dueDay}日目の${r.due.type==='raid'?'朝に防衛戦':'就寝まで'}`:''}</div><div class="grid2">${r.due.type==='debt'?btn(`${r.due.amount}G返済する`,'repay',{},'primary'):''}${btn('一日を終える','sleep',{},'')}${btn('依頼を見る','panel',{id:'quests'})}${btn('職業を変更','panel',{id:'jobs'})}</div></section>`;
if(panel==='quests')return `<section class="panel">${title('ギルドの依頼')}<div class="items">${[['gather5','採取を5回',25],['forest10','森を10歩探索',40],['raid','襲来を撃退',60]].map(([id,name,reward])=>`<div class="item"><span class="name">${name}<small>報酬 ${reward}G</small></span>${btn(r.quests.includes(id)?'完了':r.questAccepted.includes(id)?'報告':'受注','quest',{id},'small')}</div>`).join('')}</div>${btn('受付に戻る','panel',{id:'reception'},'small')}</section>`;
if(panel==='jobs')return `<section class="panel">${title('職業')}<p class="note">変更は一日1回。習得した各職業のスキルは残ります。</p><div class="grid3">${Object.entries(D.jobs).map(([id,j])=>btn(`${j.name}<br><small>${j.role}</small>`,'job',{job:id},`small ${r.job===id?'selected':''}`)).join('')}</div></section>`;
if(panel==='forge')return `<section class="panel">${title('武器屋')}<p class="note">今の装備: ${game.equipWeapon()?itemName(game.equipWeapon()):'なし'}</p><div class="grid2">${['rustySword','banditDagger','lightSword','mageStaff'].map(id=>btn(`${D.items[id].name}<br>${id==='rustySword'?35:D.items[id].sell*2}G`,'buyWeapon',{defId:id},'small')).join('')}</div></section>`;
if(panel==='ally')return petPanel();
if(panel==='tavern'){const unlocked=game.has('S44'),slots=Math.min(3,1+(E().mealSlots||0));return `<section class="panel">${title(unlocked?'酒場':'？？？')}${unlocked?`<p class="note">毎朝 ${8+(E().tavernGold||0)}G。予約 ${r.meals.length}/${slots}枠。料理は次の出撃で発動。</p><div class="reserved">${r.meals.map(id=>`<span>${D.catalog.meals.find(m=>m.id===id)?.name}</span>`).join('')||'予約なし'}</div><div class="meal-list">${D.catalog.meals.map((m,i)=>{const known=i<8||r.completed>=Math.ceil((i-7)/5);return `<div class="meal-card"><b>${known?m.name:'？？？'}</b><small>${known?`${m.cost}G · ${m.effect}`:'物語を進めると発見'}</small>${known?btn(r.meals.includes(m.id)?'予約済み':'予約','meal',{id:m.id},'small'):''}</div>`;}).join('')}</div>`:'<p>鍵のかかった店。スキルツリーの酒場「開業」で利用できます。</p>'}</section>`;}
if(panel==='board')return `<section class="panel">${title('賞金首掲示板')}<p class="note">賞金首への敗北は、今日の全収入${r.dailyGross}Gを請求されます。所持金不足なら周回終了。武器奪取率30%。</p>${r.bountyPostings.length?`<div class="items">${r.bountyPostings.map(p=>`<div class="item"><span class="name">${D.bountyDefs[p.id].name}<small>掲載 あと${p.until-r.day+1}日 / 報酬${D.bountyDefs[p.id].reward}G</small></span>${btn('受注','bounty',{id:p.id},'small')}</div>`).join('')}</div>`:'<p class="empty">今日の新しい手配書はない</p>'}${r.bountyContracts.length?`<h3>受注中</h3>${r.bountyContracts.map(p=>`<div class="statusline">${D.bountyDefs[p.id].name}　あと${p.until-r.day+1}日</div>`).join('')}`:''}</section>`;
return `<section class="panel">${title('ギルド')} ${btn('受付','panel',{id:'reception'})}</section>`;}
function raidPrepPanel(){const r=game.state.run;if(r.due.type!=='raid')return '';const party=['主人公',...r.activeAllies.slice(0,3).map(id=>D.allies[id]?.name||id),D.pets[r.pet]?.nick||'相棒'];const enemy=raidEnemy(r),days=raidDaysLeft(r);return `<section class="panel raid-prep"><h2>⚠️ 魔王軍襲来に備える</h2><strong class="raid-timer">${days===0?'襲来当日':`広場への到着まであと${days}日`}</strong><div class="raid-foe">${enemyPortrait(r.raidCount+1===D.C.totalRaids?'demonKing':`raid${r.raidCount+1}`)}<span><b>敵部隊：${esc(enemy?.name||'魔王軍')}</b><small>戦場：ギルド前の広場</small></span></div><div class="raid-party">現在の編成：${party.map(esc).join('・')}（${party.length}/5人）<br>装備・スキル・回復アイテムを確認しておこう。</div><div class="raid-actions">${btn('今すぐ広場で迎撃','defense',{},'primary')}${btn('仲間を編成','panel',{id:'ally'},'small')}${btn('装備を整える','panel',{id:'forge'},'small')}${btn('スキルを見る','tab',{id:'skills'},'small')}</div><p class="note">期限日の朝には防衛戦が自動で始まります。早期迎撃の記憶ボーナスは従来どおりです。</p></section>`;}
function guild(){const r=game.state.run;if(panel==='ally'&&!r.pendingDecree&&!r.raidFirstChoice)return `<div class="body-pad pet-workspace">${petPanel()}</div>`;if(r.pendingDecree)return `<div class="body-pad">${decreePanel()}</div>`;return `<aside class="goal-aside"><b>次の目標</b><strong>${dueText(r)}</strong><span>${r.due.dueDay?`${r.due.dueDay}日目${r.due.type==='raid'?'の朝に防衛戦':'の就寝まで'} · あと${r.due.type==='raid'?raidDaysLeft(r):game.remainingDue()}日`:'期限なし'}</span><div class="goal-aside-actions">${r.due.type==='debt'?btn('返済する','repay',{},'primary'):''}${r.due.type==='raid'?btn('広場で迎撃','defense',{},'warn'):btn('出発先を見る','tab',{id:'adventure'},'green')}${btn('就寝','sleep',{},'small')}</div><p>直近の収益 ${r.dailyGross}G · 戦利品 ${r.inventory.length}個<br>作戦　進軍 ${r.decrees?.assault||0} / 返済 ${r.decrees?.relief||0} / 研究 ${r.decrees?.research||0}</p></aside>${scene()}<div class="body-pad">${r.due.type==='raid'&&r.raidCount===D.C.totalRaids-1?'<div class="notice">二十度目の襲来を率いるのは魔王。期限日の朝、ギルド前の広場で迎え撃つ。</div>':''}${raidPrepPanel()}${guildPanel()}</div>`;}
function adventure(){const r=game.state.run,x=game.state.expedition;if(battlePlayback||x&&(x.fight||x.encounter||['raid','bounty','final'].includes(x.kind)))return battleView.render({expedition:x,run:r,data:D,playback:battlePlayback,art,sprites,button:btn,maxHp:game.maxHP(),speed:game.state.ui.battleSpeed,feedback:actionFeedback});if(x){const f=x.fight;return `${scene()}<div class="body-pad"><section class="panel">${title(x.kind==='gather'?'採取':x.kind==='dungeon'?'ダンジョン探索':x.kind==='raid'?(x.raidTier===D.C.totalRaids?'魔王との決戦':'襲来を迎え撃つ'):x.kind==='bounty'?'賞金首を倒す！':'魔王との決戦')}<div class="resource"><span>⚡ ${Math.floor(r.stamina)}</span><span>❤️ ${Math.floor(x.hp)}/${game.maxHP()}</span><span>🎒 ${x.bag.length+ x.overflow.length}個</span></div>${x.kind==='dungeon'?`<p>探索 ${x.steps}/30歩　中継点 ${r.dungeons[x.area].checkpoint}歩</p>`:''}<p class="smalltext">バッグG ${x.bagGold||0} / 仮育成点 ${x.pendingPetPoints}</p><div class="loot-strip">${x.bag.slice(-4).map(i=>`<span class="rarity-${i.rarity}">${itemIcon(i.defId,'loot-icon')} ${esc(D.items[i.defId]?.name||i.defId)}</span>`).join('')}</div>${f?`<div class="battle-card">${enemyPortrait(f.enemyId)}<b>${D.enemies[f.enemyId].name}</b>　HP ${f.enemies[0].hp}/${f.enemies[0].maxHp}<div class="progress"><i style="width:${Math.max(0,f.enemies[0].hp/f.enemies[0].maxHp*100)}%"></i></div><p class="smalltext">味方: ${f.heroes.map(a=>`${a.name} ${a.hp}/${a.maxHp}`).join(' / ')}</p></div><div class="grid2">${btn('次のラウンド','battle',{action:'attack'},'primary')}${btn('撤退を試みる','battle',{action:'retreat'},'warn')}</div><details><summary>戦闘ログを開く</summary><div class="log">${f.log.slice(-30).map(esc).join('<br>')}</div></details>`:x.encounter?`<div class="battle-card">${enemyPortrait(x.encounter.enemy)}${D.enemies[x.encounter.enemy].name}が現れた！<p class="smalltext">戦闘を始める前なら、戦利品を持って帰還できます。</p></div>${r.stamina>=D.C.battleStartCost?btn('戦闘を始める ⚡3','battle',{},'primary'):btn('スタミナ不足・戦闘を避けて帰還','return',{},'primary')}`:x.kind==='gather'?`<div class="grid2">${btn('次へ · 採取 ⚡10','gather',{count:1},'primary')}${btn('5回まとめて採取','gather',{count:5})}</div><p class="note">累計${r.petGatherCount}回 / 仮育成点${x.pendingPetPoints}。5回ごとに1点。空振りも数える。</p>`:x.kind==='dungeon'?`<div class="grid2">${btn('次へ ⚡2','step',{},'primary')}${btn('5歩探索','multiStep',{count:5},'green')}</div>`:btn('戦闘を始める ⚡3','battle',{},'primary')}<div class="row" style="margin-top:10px">${btn(`自動戦闘 ${x.auto.battle?'ON':'OFF'}`,'auto',{battle:!x.auto.battle},'small')}${x.kind==='dungeon'&&H().autoExplore?btn(`自動探索 ${x.auto.explore?'ON':'OFF'}`,'auto',{explore:!x.auto.explore},'small'):''}${btn(`速度 ${game.state.ui.battleSpeed}倍`,'speed',{},'small')}</div><div style="margin-top:10px">${btn('ギルドへ帰還','return',{},'small')}</div></section>${r.pendingWeaponReward?rewardPanel():''}</div>`;}
return worldMapUI();}
function mapAreaName(id){const place=D.worldMap.find(a=>a.id===id);if(!place)return id;if(place.kind==='guild')return 'ギルド';const def=place.kind==='gather'?D.gatherAreas.find(a=>a.id===id):D.dungeons.find(a=>a.id===id);return def?.name||id;}
function worldMapUI(){const r=game.state.run,known=r.mapDiscovered||['yard','forest'],reached=r.mapReached||[],places=D.worldMap.filter(a=>a.kind!=='guild'),visible=places.filter(a=>known.includes(a.id)),chosen=mapSelected==='guild'?null:visible.find(a=>a.id===mapSelected)||visible[0],def=chosen&&(chosen.kind==='gather'?D.gatherAreas.find(a=>a.id===chosen.id):D.dungeons.find(a=>a.id===chosen.id)),travel=def?Math.max(1,def.travel-(E().travelDiscount||0)):0,locked=def?.unlock&&!game.has(def.unlock),reward=chosen?.kind==='gather'?`主な素材: ${D.items[def.commonItem].name} / 希少: ${D.items[def.rareItem].name}`:chosen?`魔物: ${D.enemies[def.enemy].name} / ボス: ${D.enemies[def.boss].name} / 戦利品と${D.items[def.book].name}`:'',unseen=places.length-visible.length;
const circles=[{x:19,y:62,id:'guild'},...visible].map(a=>`<div class="map-reveal ${mapReveal.includes(a.id)?'newly':''}" style="--x:${a.x}%;--y:${a.y}%;--radius:${a.id==='guild'?17:23}%;background-image:url('world-map-v1.png')"></div>`).join('');
mapReveal=[];const pins=[D.worldMap[0],...visible].map(a=>`<button class="map-pin ${a.kind} ${chosen?.id===a.id?'selected':''} ${reached.includes(a.id)?'reached':''}" style="left:${a.x}%;top:${a.y}%" data-act="mapSelect" data-arg='{"id":"${a.id}"}' title="${esc(mapAreaName(a.id))}"><span>${a.mark}</span><small>${esc(mapAreaName(a.id))}</small></button>`).join('');
return `<div class="world-screen"><div class="world-map" aria-label="霧に包まれたワールドマップ"><div class="map-fog"></div>${circles}<div class="map-vignette"></div>${pins}<div class="map-legend pixel"><span>✿ 採取</span><span>⚔ 探索</span><span>未発見 ${unseen}</span></div></div><aside class="map-details pixel">${chosen?`<div class="map-kind">${chosen.kind==='gather'?'✿ 採取地':'⚔ 探索地'} · ${reached.includes(chosen.id)?'到達済み':'発見済み'}</div><h2>${esc(mapAreaName(chosen.id))}</h2><p>${esc(chosen.description)}</p><div class="map-facts"><span>移動 ⚡${travel}</span><span>${chosen.kind==='gather'?`成功 ${Math.round((1-def.empty)*100)}%`:`中継点 ${r.dungeons[chosen.id].checkpoint}歩`}</span></div><p class="map-reward">${esc(reward)}</p>${locked?`<div class="notice">${esc(D.nodeMap[def.unlock]?.name||def.unlock)}を取得すると出発できます</div>`:btn(`この場所へ出発 ⚡${travel}`,'depart',{kind:chosen.kind,area:chosen.id},'primary map-depart')}`:`<h2>ギルド</h2><p>旅の始まりと帰る場所。</p>${btn('ギルドへ','mapGuild',{},'primary map-depart')}`}<div class="map-special">${r.due.type==='final'?btn('旧版の決戦を続ける','depart',{kind:'final'},'warn'):''}${r.bountyContracts.map(c=>btn(`${D.bountyDefs[c.id].name}へ挑戦`,'depart',{kind:'bounty',area:c.id},'warn')).join('')}</div></aside></div>`;}
function rewardPanel(){const reward=game.state.run.pendingWeaponReward;return `<section class="panel">${title('武器を一つ選ぶ')}<div class="items">${reward.candidates.map((c,i)=>`<div class="item">${itemIcon(c.stolen?c.item.defId:c.defId)}<span class="name">${c.stolen?'奪われた武器: ':''}${D.items[c.stolen?c.item.defId:c.defId].name}</span>${btn('選ぶ','chooseWeapon',{index:i},'small')}</div>`).join('')}</div></section>`;}
function bulkSaleBar(){const all=game.bulkSaleItems('all'),half=game.bulkSaleItems('half');if(game.state.expedition||!all.length)return '';const total=items=>items.reduce((sum,item)=>sum+game.salePrice(item),0);return `<details class="bulk-tools"><summary>素材と換金品を一括売却</summary><div class="row">${btn(`全部売る ${all.length}個・${total(all)}G`,'sellBulk',{mode:'all'},'small')}${half.length?btn(`半分売る ${half.length}個・${total(half)}G`,'sellBulk',{mode:'half'},'small'):''}</div></details>`;}
function stackDetails(group){
  const first=group.entries[0],def=D.items[first.defId],story=window.ItemLore.description(first.defId,def),total=group.entries.reduce((sum,item)=>sum+game.salePrice(item),0);
  return `<div class="stack-backdrop" data-act="closeStack"></div><section class="stack-detail rarity-${first.rarity}" role="dialog" aria-modal="true" aria-label="${esc(itemName(first))}の詳細"><button class="stack-close" data-act="closeStack" aria-label="閉じる">×</button><div class="stack-kicker">${esc(D.rarityLabels[first.rarity])} · ${esc(def?.kind==='material'?'採取した素材':'旅の戦利品')}</div><h2>${itemIcon(first.defId,'stack-icon')}${esc(itemName(first))} <small>×${group.entries.length}</small></h2><p class="stack-lore">${esc(story.lore)}</p>${story.use?`<div class="stack-use"><b>使い道</b><p>${esc(story.use)}</p></div>`:''}<div class="stack-facts"><span>所持 ${group.entries.length}個</span><span>1個 ${game.salePrice(first)}G</span><span>合計 ${total}G</span></div><div class="grid2">${btn(`1個売る · ${game.salePrice(first)}G`,'sell',{uid:first.uid},'small')}${btn(`まとめて売る · ${group.entries.length}個`,'sellStack',{uids:group.entries.map(item=>item.uid)},'primary')}</div></section>`;
}
function items(){
  const r=game.state.run;
  const counts=Object.fromEntries(inventoryGroups.map(([id])=>[id,r.inventory.filter(item=>inventoryGroup(item)===id).length]));
  const current=inventoryTab||inventoryGroups.find(([id])=>counts[id])?.[0]||'equipment';
  const visible=r.inventory.filter(item=>inventoryGroup(item)===current);
  const stacks=inventoryStacks(visible);
  const selected=stacks.find(group=>group.key===selectedStackKey);
  return `<div class="body-pad"><section class="panel inventory-panel">${title('宝物庫')}
    <div class="inventory-tabs" role="tablist" aria-label="持ち物の種類">${inventoryGroups.map(([id,label])=>`<button class="inventory-tab ${current===id?'active':''}" role="tab" aria-selected="${current===id}" data-act="inventoryTab" data-arg='{"id":"${id}"}'>${label}<span>${counts[id]}</span></button>`).join('')}</div>
    ${['material','treasure'].includes(current)?bulkSaleBar():''}
    <div class="items">${stacks.map(({key,entries})=>{const i=entries[0],d=D.items[i.defId],kind=d?.kind;return stackable(i)?`<button class="item item-stack rarity-${i.rarity}" data-act="openStack" data-arg='${esc(JSON.stringify({key}))}'>${itemIcon(i.defId)}<span class="name">${esc(d.name)} ×${entries.length}<small>${D.rarityLabels[i.rarity]} · 合計 ${entries.reduce((sum,item)=>sum+game.salePrice(item),0)}G</small></span><span aria-hidden="true">詳細 ›</span></button>`:`<div class="item rarity-${i.rarity}">${itemIcon(i.defId)}<span class="name">${esc(itemName(i))} ${i.level?'+'+i.level:''}${[r.weaponUid,r.armorUid,r.accessoryUid].includes(i.uid)?'【装備中】':''}<small>${D.rarityLabels[i.rarity]} · ${esc(d?.description||'')} · 売値${game.salePrice(i)}G</small></span><div class="row">${kind==='weapon'?btn('装備','equip',{uid:i.uid},'small')+btn('強化','upgrade',{uid:i.uid},'small'):''}${['armor','accessory'].includes(kind)?btn('装備','equipGear',{uid:i.uid},'small'):''}${kind==='book'?btn('読む','readBook',{uid:i.uid},'small'):''}${['tome','consumable'].includes(kind)?btn('使う','use',{uid:i.uid},'small'):''}${kind==='respec'?btn('振り直す','respecPick',{uid:i.uid},'small'):''}${btn('売る','sell',{uid:i.uid},'small')}</div></div>`;}).join('')||`<p class="empty">${r.inventory.length?'この種類の持ち物はありません。':'まだ何もない。探索や採取へ出よう。'}</p>`}</div>
    ${selected?stackDetails(selected):''}
  </section>${r.artisan?`<section class="panel">${title('加工場')}<p>採ってきた薬草を2束、職人の作業台へ。冒険を続けるあいだにじっくり煎じて、傷を癒やすポーションに仕上げます。</p><p class="note">仕込み後、通常行動でスタミナ30消費すると完成。作業中 ${r.processing.length}件。</p>${btn('薬草2束を仕込む','process',{},'primary')}</section>`:''}</div>`;
}
function more(){const r=game.state.run,m=game.state.meta;return `<div class="body-pad">${m.ended?`<div class="ending"><h1>夜明け</h1><p>ギルドの仲間たちは帰る場所を守り抜いた。</p><h2>Thank you for playing</h2></div>`:''}<section class="panel">${title('旅の記録')}<div class="grid2"><div class="statusline">${m.rounds}周目</div><div class="statusline">記憶 ${m.memory}</div><div class="statusline">返済 ${r.debtCount}/${D.C.totalDebts} · 襲来 ${r.raidCount}/${D.C.totalRaids}</div><div class="statusline">図鑑 ${m.catalog.length}品</div></div><p class="note">現世の獲得収入 ${r.eligibleGross}G。失敗時、10Gごとに記憶1点。</p></section><section class="panel">${title('実績')}<p>${m.achievements.length}件解除</p>${m.achievements.map(id=>`<div class="statusline">実績解除！ ${esc(achievementNames[id]||'旅の記録')}</div>`).join('')||'<p class="note">まだ実績がない</p>'}</section><section class="panel">${title('図鑑')}<div class="row">${m.catalog.map(id=>`<span class="statusline catalog-entry">${itemIcon(id)}${D.items[id]?.name||id}</span>`).join('')||'まだ記録がない'}</div></section><section class="panel">${title('保存と設定')}<div class="grid2">${btn('セーブを書き出す','export',{},'small')}${btn('セーブを読み込む','import',{},'small')}${btn(game.state.ui.mute?'音を出す':'消音する','mute',{},'small')}${btn('遊び方','help',{},'small')}</div></section>${art.galleryHTML(esc)}${r.due.type==='heaven'?heaven():''}</div>`;}
function heaven(){const m=game.state.meta;return `<section class="panel">${title('天界 — 次の旅への記憶')}<p>記憶 ${m.memory}点。現世の失敗で得た力は次の周回に残る。</p>${btn('天界のスキルツリー','openTree',{id:'heaven'},'primary')}<div class="sep"></div><h3>何度でも鍛える</h3><p class="note">記憶で永続強化。取得段階が上がるほど必要な記憶も増えます。</p>${[['assault','攻勢','全員の攻撃を強化'],['guard','守護','HPと防御を強化'],['livelihood','生計','初期G、スタミナ、素材売値を強化']].map(([id,name,desc])=>`<div class="item"><span class="name">${name} Lv.${m.training?.[id]||0}<small>${desc}</small></span>${btn(`${game.trainingCost(id)}記憶で鍛える`,'buyTraining',{track:id},'small')}</div>`).join('')}<div class="sep"></div><h3>発見した品の追求</h3><p class="note">出現率の追加抽選を選べます。未発見の品は表示されません。</p>${m.catalog.map(id=>`<div class="item"><span class="name">${D.items[id]?.name||id}</span>${m.pursuitOwned.includes(id)?btn(m.pursuitOn.includes(id)?'ON':'OFF','pursuitToggle',{defId:id},'small'):btn('解放 5点','pursuitBuy',{defId:id},'small')}</div>`).join('')}<div class="sep"></div>${btn('強くてニューゲーム','restart',{},'primary')}</section>`;}
function help(){return `<div class="body-pad"><section class="panel">${title('遊び方')}<p>返済と襲来は各20回。最初の返済は五日目の就寝まで。以後は達成日から4日後が次の目標日です。魔王軍は到着日の朝にギルド前の広場へ襲来し、自動で防衛戦が始まります。早めに広場へ出て迎撃することもできます。20回目の襲来を率いるのは魔王です。採取や冒険の報酬をスキルに投資しましょう。</p><p>移動・採取・探索・戦闘はスタミナを使います。帰還しても残量は維持。就寝で日付が進み、回復します。</p><p>戦闘敗北では疲労して戻ります。期限切れや破産では天界へ進み、記憶で恒久強化を買って再出発します。</p><p>襲来を3回撃退するごとに作戦会議が開きます。進軍・返済・研究から選び、その周の戦い方を変えられます。</p><p>スキルツリーは指で動かし、二本指で拡大縮小できます。星をタップして説明と購入条件を確認できます。</p>${btn('チュートリアルをもう一度見る','replayTutorial',{},'small')}${btn('戻る','helpClose')}</section></div>`;}
function confirmUI(){
  if(!pendingConfirm)return '';
  const sale=pendingConfirm.type==='sale'||pendingConfirm.type==='stack',selected=pendingConfirm.type==='stack'?game.state.run.inventory.filter(item=>pendingConfirm.uids.includes(item.uid)):sale?game.bulkSaleItems(pendingConfirm.mode):[],gold=selected.reduce((sum,item)=>sum+game.salePrice(item),0);
  const r=game.state.run;const message=sale?`${selected.length}個をまとめて売り、${gold}Gを受け取りますか？`:`一日を終えますか？${r.due.type==='raid'&&r.day+1>=r.due.dueDay?' 明日の朝、ギルド前の広場で魔王軍防衛戦が始まります。':r.due.dueDay===r.day?' 今日が返済期限です。未達成なら周回終了します。':''}`;
  return `<div class="confirm-backdrop" data-act="cancelConfirm"></div><div class="confirm-dialog" role="dialog" aria-modal="true" aria-label="操作の確認"><h2>${sale?'まとめて売る':'一日進める'}</h2><p>${message}</p><div class="confirm-actions">${btn('やめる','cancelConfirm',{},'small')}${btn(sale?'売却する':'一日進める','acceptConfirm',{},'primary')}</div></div>`;
}
function render(){const s=game.state,r=s.run;if(!r.job){app.innerHTML=intro();return;}if(tab==='tree'||tab==='skills'){if(tab==='skills')tree='all';if(view._id!==tree){const saved=s.ui.treeViews[tree];view=saved?{...saved,_id:tree}:{x:0,y:0,zoom:tree==='all'?.55:.65,_id:tree};}app.innerHTML=treeUI();treeCanvas=document.querySelector('.tree-canvas');setupTree();return;}if(tab==='help'){app.innerHTML=`${hud()}<main class="main">${help()}</main>${nav()}`;return;}if(!battlePlayback){if(r.pendingDecree)tab='guild';else if(r.due.type==='heaven')tab='more';}if(s.expedition&&tab==='guild')tab='adventure';app.innerHTML=`${hud()}<main class="main">${tab==='guild'?guild():tab==='adventure'?adventure():tab==='items'?items():more()}</main>${nav()}${tutorialUI()}${confirmUI()}${raidWarningUI()}${petLevelUI()}`;motionActive=false;const x=s.expedition;if(tab==='adventure'&&x&&!app.querySelector('.combat-screen')){if(x.fight){const extra=[];if(r.job==='priest')extra.push(btn('ヒール','battle',{action:'heal'},'green'));if(r.inventory.some(i=>i.defId==='potion'))extra.push(btn('ポーション','battle',{action:'potion'},'green'));if(extra.length)app.querySelector('.battle-card')?.insertAdjacentHTML('afterend',`<div class="row">${extra.join('')}</div>`);}app.querySelector('.body-pad .panel')?.insertAdjacentHTML('beforeend',`<details><summary>自動停止の条件</summary><div class="grid2">${[['stopBoss','ボス前'],['stopRare','発見時'],['stopBag','バッグ満杯'],['stopLowHp','HP低下']].map(([key,label])=>btn(`${label} ${x.auto[key]?'ON':'OFF'}`,'auto',{[key]:!x.auto[key]},'small')).join('')}</div></details>`);}}
function treeData(){return tree==='heaven'?D.heavenTree:{id:'all',name:'スキルの星図',color:'#f2ce7e'};}
function nodesForTree(){if(tree==='all')return window.SkillMap.visible(game,D);const raw=[...D.heavenTree.nodes,...(game.state.meta.everStolen?D.weaponProtect:[])],owned=game.state.meta.heavenSkills;return raw.filter(n=>owned.includes(n.nodeId)||game.canBuyNode(n.nodeId,true));}
function nodePosition(n){return tree==='all'?skillMap.position(n):{x:n.x,y:n.y};}
function focusTreeGroup(id){const label=skillMap.labels.find(item=>item.id===id);if(!label)return;view.zoom=Math.max(view.zoom,.62);view.x=-label.x*view.zoom;view.y=-label.y*view.zoom;treeCanvas?._draw?.();game.dispatch('SAVE_TREE_VIEW',{id:tree,x:view.x,y:view.y,zoom:view.zoom});}
function fitTree(){const nodes=nodesForTree(),points=tree==='all'?[{x:0,y:0},...nodes.map(nodePosition)]:nodes.map(nodePosition),canvas=treeCanvas;if(!canvas||!points.length)return;const rect=canvas.getBoundingClientRect(),minX=Math.min(...points.map(p=>p.x)),maxX=Math.max(...points.map(p=>p.x)),minY=Math.min(...points.map(p=>p.y)),maxY=Math.max(...points.map(p=>p.y));view.zoom=clamp(Math.min((rect.width-60)/(maxX-minX+110),(rect.height-60)/(maxY-minY+110)),tree==='all'?.1:D.C.skillZoomMin,D.C.skillZoomMax);view.x=-(minX+maxX)/2*view.zoom;view.y=-(minY+maxY)/2*view.zoom;canvas._draw?.();game.dispatch('SAVE_TREE_VIEW',{id:tree,x:view.x,y:view.y,zoom:view.zoom});}
function treeDetail(n){
  if(!n||!nodesForTree().includes(n))return '<p class="note">星をタップして力を調べる。遠くの星の正体は、道を開くまで分かりません。</p>';
  const all=tree==='all',r=game.state.run,m=game.state.meta;
  if(all&&!window.SkillMap.revealed(game,n))return '<h3>まだ名のない星</h3><p>この先に眠る力は、手前の星を手に入れてから明らかになります。</p>';
  const action=(all?r.skills:m.heavenSkills).includes(n.nodeId)?'<span class="tree-owned">✓ 取得済み</span>':game.canBuyNode(n.nodeId,!all)?btn('取得する','buyTree',{id:n.nodeId},'primary'):'<button class="btn primary" disabled>取得条件を確認</button>';
  return `<h3>${esc(n.name)} <small>${all?esc(skillMap.groups.find(g=>g.id===n.treeId)?.name||'秘伝'):'天界'} / ${D.rarityLabels[n.rarity]||''}</small></h3><p>${esc(n.description)}</p><p>費用 ${all?game.skillCost(n):n.costG}${all?'G':'記憶'}　前提: ${n.prerequisites?.length?n.prerequisites.map(id=>D.nodeMap[id]?.name||id).join('、'):'なし'}</p>${action}`;
}
function treeUI(){
  const t=treeData(),r=game.state.run,m=game.state.meta,n=selected?D.nodeMap[selected]:null,nodes=nodesForTree(),available=nodes.filter(node=>game.canBuyNode(node.nodeId,tree==='heaven')).length,all=tree==='all';
  const branchSelect=all?`<select id="tree-select" aria-label="系統へ移動"><option value="">系統へ移動</option>${skillMap.groups.map(group=>`<option value="${group.id}">${esc(group.name)}</option>`).join('')}</select>`:'';
  return `<div class="tree-view"><div class="tree-top"><button data-act="closeTree" data-arg='{"tab":"${all?'guild':'more'}"}'>← 戻る</button><strong>${esc(t.name)}</strong>${branchSelect}<input id="tree-search" placeholder="発見したスキルを検索" value="${esc(search)}" aria-label="発見したスキルを検索"><button data-act="treeFit" aria-label="全体を表示">全体</button><button data-act="treeZoom" data-arg='{"delta":-0.2}' aria-label="縮小">−</button><button data-act="treeZoom" data-arg='{"delta":0.2}' aria-label="拡大">＋</button><div class="meta">取得可能 ${available}・${all?`${r.gold}G`:`記憶 ${m.memory}`}</div></div><canvas class="tree-canvas" aria-label="${esc(t.name)}"></canvas><div class="tree-detail">${treeDetail(n)}</div></div>`;
}
function setupTree(){
  const canvas=treeCanvas,ctx=canvas.getContext('2d'),all=tree==='all';
  function draw(){
    const rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;
    canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);
    const w=rect.width,h=rect.height,zoom=view.zoom,nodes=nodesForTree(),visible=new Set(nodes.map(n=>n.nodeId));
    ctx.clearRect(0,0,w,h);ctx.fillStyle='#111624';ctx.fillRect(0,0,w,h);
    for(let i=0;i<130;i++){const px=(i*211.37+Math.sin(i*17.2)*91+w*5)%w,py=(i*139.73+Math.cos(i*4.7)*63+h*5)%h;ctx.fillStyle=i%9===0?'#dabf8b99':'#8d9ab566';ctx.fillRect(px,py,i%13===0?2:1,i%13===0?2:1);}
    ctx.save();ctx.translate(w/2+view.x,h/2+view.y);ctx.scale(zoom,zoom);
    if(all){
      ctx.shadowBlur=18;ctx.shadowColor='#f6cb80';ctx.fillStyle='#d9ac64';ctx.beginPath();ctx.arc(0,0,35,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#29283a';ctx.beginPath();ctx.arc(0,0,30,0,Math.PI*2);ctx.fill();ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='bold 27px "Segoe UI Symbol",sans-serif';ctx.fillStyle='#fce1a2';ctx.fillText('⚜',0,1);
      for(const label of skillMap.labels){
        ctx.strokeStyle=label.color+'55';ctx.lineWidth=2/zoom;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(label.x,label.y);ctx.stroke();
        ctx.fillStyle=label.color;ctx.beginPath();ctx.arc(label.x,label.y,4,0,Math.PI*2);ctx.fill();
      }
      for(const n of nodes){if((n.prerequisites||[]).length)continue;const label=skillMap.labels.find(item=>item.id===n.treeId),to=nodePosition(n);if(!label)continue;ctx.strokeStyle=label.color+'90';ctx.lineWidth=2/zoom;ctx.beginPath();ctx.moveTo(label.x,label.y);ctx.lineTo(to.x,to.y);ctx.stroke();}
    }
    for(const n of nodes){for(const id of n.prerequisites||[]){if(!visible.has(id))continue;const parent=D.nodeMap[id];if(!parent)continue;const from=nodePosition(parent),to=nodePosition(n),awake=!all||window.SkillMap.revealed(game,n);ctx.strokeStyle=awake?((all?skillMap.groups.find(g=>g.id===n.treeId)?.color:'#a39470')||'#a39470'):'#657080';ctx.globalAlpha=awake?.7:.25;ctx.lineWidth=awake?3/zoom:2/zoom;ctx.setLineDash(awake?[]:[5/zoom,7/zoom]);ctx.beginPath();ctx.moveTo(from.x,from.y);ctx.lineTo(to.x,to.y);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;}}
    const owned=all?game.state.run.skills:game.state.meta.heavenSkills;
    for(const n of nodes){
      const p=nodePosition(n),hit=!!search&&(!all||window.SkillMap.revealed(game,n))&&`${n.name} ${n.nodeId}`.toLowerCase().includes(search.toLowerCase());
      skillIcons.draw(ctx,n,p.x,p.y,{owned:owned.includes(n.nodeId),available:game.canBuyNode(n.nodeId,!all),selected:hit||n.nodeId===selected});
    }
    ctx.restore();
  }
  draw();canvas._draw=draw;
  const pointers=new Map();let gestureMoved=false;
  canvas.onpointerdown=e=>{if(pointers.size)gestureMoved=true;else gestureMoved=false;canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY});};
  canvas.onpointermove=e=>{
    if(!pointers.has(e.pointerId))return;
    const old=pointers.get(e.pointerId),other=[...pointers.entries()].find(([id])=>id!==e.pointerId)?.[1];
    pointers.set(e.pointerId,{x:e.clientX,y:e.clientY,startX:old.startX,startY:old.startY});
    if(other){const before=Math.hypot(old.x-other.x,old.y-other.y),after=Math.hypot(e.clientX-other.x,e.clientY-other.y);view.zoom=clamp(view.zoom*after/Math.max(1,before),all?.1:D.C.skillZoomMin,D.C.skillZoomMax);view.x+=(e.clientX-old.x)/2;view.y+=(e.clientY-old.y)/2;gestureMoved=true;}
    else{view.x+=e.clientX-old.x;view.y+=e.clientY-old.y;if(Math.hypot(e.clientX-old.startX,e.clientY-old.startY)>7)gestureMoved=true;}
    draw();
  };
  canvas.onpointerup=e=>{
    if(!pointers.has(e.pointerId))return;pointers.delete(e.pointerId);
    if(!gestureMoved){const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left-rect.width/2-view.x)/view.zoom,y=(e.clientY-rect.top-rect.height/2-view.y)/view.zoom;const node=nodesForTree().find(n=>{const p=nodePosition(n);return Math.hypot(p.x-x,p.y-y)<(skillIcons.radius(n)+8)/view.zoom;});if(node){selected=node.nodeId;render();return;}}
    game.dispatch('SAVE_TREE_VIEW',{id:tree,x:view.x,y:view.y,zoom:view.zoom});
  };
  canvas.onwheel=e=>{e.preventDefault();view.zoom=clamp(view.zoom+(e.deltaY<0?.12:-.12),all?.1:D.C.skillZoomMin,D.C.skillZoomMax);draw();};
  window.addEventListener('resize',draw,{once:true});
}
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
app.addEventListener('click',e=>{const job=e.target.closest('[data-pick-job]');if(job){introJob=job.dataset.pickJob;render();return;}const pet=e.target.closest('[data-pick-pet]');if(pet){introPet=pet.dataset.pickPet;render();return;}const nt=e.target.closest('[data-tab]');if(nt){if(battleAnimating)cancelBattle();tab=nt.dataset.tab;if(tab==='skills'){tree='all';selected=null;search='';}if(tutorialStep==='map'&&tab==='adventure')setTutorial('depart');if(tutorialStep==='items'&&tab==='items'){inventoryTab='material';setTutorial('openStack');}render();return;}const pn=e.target.closest('[data-panel]');if(pn){panel=pn.dataset.panel;tab='guild';render();return;}const el=e.target.closest('[data-act]');if(!el)return;const a=el.dataset.act,p=JSON.parse(el.dataset.arg||'{}');switch(a){case 'start':if(!introPet){showToast('相棒を選んでください');break;}send('CHOOSE_START',{job:introJob,pet:introPet});break;case 'tab':tab=p.id;if(tab==='skills'){tree='all';selected=null;search='';}if(tutorialStep==='map'&&tab==='adventure')setTutorial('depart');if(tutorialStep==='items'&&tab==='items'){inventoryTab='material';setTutorial('openStack');}render();break;case 'panel':panel=p.id;tab='guild';render();break;case 'openTree':tree=p.id;selected=null;search='';view._id=null;tab='tree';render();break;case 'closeTree':tab=p.tab;render();break;case 'treeFit':fitTree();break;case 'treeZoom':view.zoom=clamp(view.zoom+p.delta,tree==='all'?.1:D.C.skillZoomMin,D.C.skillZoomMax);treeCanvas?._draw?.();break;case 'chooseDecree':send('CHOOSE_DECREE',p);break;case 'buyTraining':send('BUY_TRAINING',p);break;case 'buyTree':send(tree==='heaven'?'BUY_HEAVEN':'BUY_SKILL',{id:p.id});break;case 'repay':send('REPAY');break;case 'sleep':pendingConfirm={type:'sleep'};render();break;case 'mapSelect':mapSelected=p.id;render();break;case 'mapGuild':tab='guild';render();break;case 'depart':send('DEPART',p);break;case 'gather':send('GATHER',p);break;case 'step':send('STEP');break;case 'multiStep':{const before=actionEffects.capture(game.state);let discoveries=[];for(let i=0;i<p.count;i++){const result=game.dispatch('STEP');discoveries.push(...(result.mapDiscoveries||[]));if(result.type==='error'||game.state.expedition?.encounter)break;}motionActive=true;setActionFeedback(actionEffects.derive(before,game.state,game.state.lastResult,'STEP',D));if(actionFeedback)playActionSound(actionFeedback);if(discoveries.length)mapReveal=[...new Set([...mapReveal,...discoveries])];if(discoveries.length)showToast(`地図を発見！ ${discoveries.map(mapAreaName).join('・')}`);else if(!actionFeedback)showToast(game.state.lastResult.message);else document.querySelector('.toast')?.remove();render();break;}case 'battle':if(!battleAnimating)send('BATTLE',p);break;case 'defense':send('START_DEFENSE');break;case 'ackRaidWarning':{const seen={...(game.state.ui.raidWarningsSeen||{}),[p.key]:true};game.dispatch('SET_UI',{raidWarningsSeen:seen});render();break;}case 'auto':send('SET_AUTO',p);break;case 'speed':send('SET_UI',{battleSpeed:game.state.ui.battleSpeed===1?2:1});break;case 'return':if(!battleAnimating)send('RETURN');break;case 'job':send('SET_JOB',p);break;case 'levelPet':send('LEVEL_PET',p);break;case 'petGrowthDismiss':petLevelAnimation=null;clearTimeout(petLevelTimer);render();break;case 'switchPet':send('SWITCH_PET',p);break;case 'petSkill':send('CHOOSE_PET_SKILL',p);break;case 'chooseAlly':send('CHOOSE_ALLY',p);break;case 'hireAlly':send('HIRE_ALLY',p);break;case 'allyToggle':send('SET_ALLY',p);break;case 'buyWeapon':send('BUY_WEAPON',p);break;case 'upgrade':send('UPGRADE_WEAPON',p);break;case 'equip':send('EQUIP_WEAPON',p);break;case 'equipGear':send('EQUIP_GEAR',p);break;case 'readBook':send('READ_BOOK',p);break;case 'meal':{const slots=Math.min(3,1+(E().mealSlots||0));if(game.state.run.meals.length>=slots&&!game.state.run.meals.includes(p.id)){const choices=game.state.run.meals.map(id=>D.catalog.meals.find(m=>m.id===id)?.name).join(' / ');const old=prompt(`置き換える料理のIDを入力してください: ${choices}\n${game.state.run.meals.join(' / ')}`);if(!old)break;p.replace=old;}send('BUY_MEAL',p);break;}case 'bounty':send('ACCEPT_BOUNTY',p);break;case 'chooseWeapon':send('CHOOSE_BOUNTY_WEAPON',p);break;case 'inventoryTab':inventoryTab=p.id;selectedStackKey=null;render();break;case 'openStack':selectedStackKey=p.key;if(tutorialStep==='openStack')setTutorial('sell');render();break;case 'closeStack':selectedStackKey=null;render();break;case 'sellStack':if(p.uids?.length){pendingConfirm={type:'stack',uids:p.uids};render();}break;case 'sell':send('SELL_ITEM',p);break;case 'sellBulk':if(game.bulkSaleItems(p.mode).length){pendingConfirm={type:'sale',mode:p.mode};render();}break;case 'cancelConfirm':pendingConfirm=null;render();break;case 'acceptConfirm':{const action=pendingConfirm;pendingConfirm=null;if(action?.type==='sale')send('SELL_BULK',{mode:action.mode});else if(action?.type==='stack')send('SELL_STACK',{uids:action.uids});else if(action?.type==='sleep')send('SLEEP');break;}case 'use':send('USE_ITEM',p);break;case 'process':send('START_PROCESS',p);break;case 'respecPick':{const names=D.trees.map(t=>t.id);const id=prompt(`振り直すツリーIDを入力:\n${names.join(' / ')}`);if(id)send('RESPEC',{uid:p.uid,tree:id});break;}case 'quest':send('ACCEPT_QUEST',p);break;case 'pursuitBuy':send('BUY_PURSUIT',p);break;case 'pursuitToggle':send('TOGGLE_PURSUIT',p);break;case 'restart':send('RESTART');tab='guild';break;case 'export':{const blob=new Blob([game.exportSave()],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='guild-save.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);break;}case 'import':{const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files[0];if(!file)return;const result=game.importSave(await file.text());showToast(result.message);render();};input.click();break;}case 'mute':send('SET_UI',{mute:!game.state.ui.mute});break;case 'skipTutorial':setTutorial('done');render();break;case 'replayTutorial':setTutorial('map');tab='guild';render();break;case 'help':tab='help';render();break;case 'helpClose':tab='more';render();break;}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&pendingConfirm){pendingConfirm=null;render();}});
app.addEventListener('change',e=>{if(e.target.id==='tree-select'&&e.target.value){focusTreeGroup(e.target.value);e.target.value='';}});
app.addEventListener('input',e=>{if(e.target.id==='tree-search'){search=e.target.value;const matches=nodesForTree().filter(n=>(tree!=='all'||window.SkillMap.revealed(game,n))&&(n.name.includes(search)||n.nodeId.toLowerCase().includes(search.toLowerCase())));if(search&&matches.length){const n=matches[0],p=nodePosition(n);view.x=-p.x*view.zoom;view.y=-p.y*view.zoom;selected=n.nodeId;app.querySelector('.tree-detail').innerHTML=treeDetail(n);}treeCanvas?._draw?.();}});
let lastAuto=0;setInterval(()=>{const x=game.state.expedition;if(!x||tab!=='adventure'||document.hidden||battleAnimating)return;const now=Date.now(),delay=game.state.ui.battleSpeed===2?320:650;if(now-lastAuto<delay)return;lastAuto=now;if(x.auto.battle&&(x.fight||x.encounter)){battleSend({action:'attack'});return;}if(x.kind==='dungeon'&&x.auto.explore&&!x.fight&&!x.encounter){if(game.state.run.stamina<D.C.stepCost||x.auto.stopLowHp&&x.hp<game.maxHP()*.3||x.auto.stopBag&&x.bag.length>=D.C.bagSlots){game.dispatch('SET_AUTO',{explore:false});render();return;}const before=actionEffects.capture(game.state);const result=game.dispatch('STEP');setActionFeedback(actionEffects.derive(before,game.state,result,'STEP',D));if(actionFeedback)playActionSound(actionFeedback);motionActive=true;const fresh=result.mapDiscoveries||[];if(fresh.length){mapReveal=[...new Set([...mapReveal,...fresh])];showToast(`地図を発見！ ${fresh.map(mapAreaName).join('・')}`);}if(result.type==='boss'&&x.auto.stopBoss||result.type==='item'&&x.auto.stopRare)game.dispatch('SET_AUTO',{explore:false});render();}},180);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game.state.expedition){game.state.expedition.auto.explore=false;game.state.expedition.auto.battle=false;game.snapshot();}});
render();
